package com.veyra.notification;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;@Component public class ReminderScheduler{private final JdbcTemplate db;public ReminderScheduler(JdbcTemplate d){db=d;}@Scheduled(fixedDelay=60000)public void reminders(){db.update("insert into notifications(user_id,event_type,channel,template_code,dedupe_key,data,scheduled_for) select d.user_id,'booking.reminder','PUSH','DRIVER_BOOKING_REMINDER','driver-reminder-'||sb.id,jsonb_build_object('bookingId',sb.id),now() from scheduled_bookings sb join drivers d on d.id=sb.selected_driver_id where sb.status='CONFIRMED' and sb.scheduled_at between now()+interval '55 minutes' and now()+interval '65 minutes' on conflict(dedupe_key) do nothing");}}